## Functions to generate phase plots + trajs + mean rewards

# Obtain dX as a function of X for phase plots
# Also works when N=2 or Z=2
def obtain_dXs(aei,  # agent-environment interface
               res,  # range & resolution of strategies
               xinds:tuple,  # of indices of the phase space object to plot along the x axis
               traj_len:int,  # trajectory len
               otherXs=None,  # when N=2 or Z=2: values of X in 2nd condition
               ):
        
    l = len(res)
    dXs = np.zeros((aei.Z, l))  # will store the dXs

    for i in range(aei.Z):
        
        for j, xval in enumerate(res):  # loop over Xs
            
            if (aei.N > 1) or (aei.Z > 1): # 2 states or 2 actions
                xval_ = otherXs[j]
            else:
                xval_ = None
                
            X = obtain_Xs(aei, xinds, xval, xval_)  # create X with values along all dims
            prederror = aei.TDerror(X, norm=True)  # compute pred error
            dX = aei.step(X)[0] - X  # compute dX
            dXs[i, j] = dX[xinds[0], i, xinds[2]][0]  # dX for i,s,a of interest
            
    return dXs


def obtain_Xs(aei,  # CRLD multi-agent environment object
              xinds:tuple,  # of indices of the phase space item to plot along the x axis
              xval:float,  # the value of the phase space item to plot along the x axis
              xval_:float  # the value of X in the 2nd condition
              ): 
    
    N, C, M = aei.N, aei.Z, aei.M  # Number of agents, states, actions
    
    Xs = np.zeros((N, C, M))  # will store the Xs
    
    xi, xc, xa = xinds  # plotted agent, state, action
    xa_ = tuple(set(range(M)) - set(xa))  # other action
    
    Xs[xi, xc, xa] = xval  # setting x value
    
    # probability of taking other action
    Xs[xi,xc,xa_] = 1-Xs[xi, xc, xa]
    
    if C > 1:  # more than one state
        xc_ = tuple(set(range(C)) - set(xc))  # other state
        Xs[xi, xc_, xa] = xval_  # strategy in state 2 for action 1
        Xs[xi, xc_, xa_] = 1 - Xs[xi, xc_, xa]  # strategy in state 2 for action 2
    if N > 1:  # more than 1 agent
        xi_ = tuple(set(range(N)) - set(xi))  # other agent
        Xs[xi_, xc, xa] = xval_  # other agent's strategy for action 1
        Xs[xi_, xc, xa_] = 1 - Xs[xi_, xc, xa]  # other agent's strat for action 2
    
    return Xs

# Compute X traj and reward traj
def reward_traj(aei,  # CRLD multi-agent environment object
                X:tuple,  # strategy
                i,  # agent
                traj_len:int=500,  # trajectory length
                ): 
    
    r_traj = np.zeros((traj_len))  # will store rewards
    # Compute X trajectory
    traj, fpreached = aei.trajectory(X, traj_len) 
    # Compute reward trajectory
    for t in range(traj_len):
        r_traj[t] = aei.Ri(traj[t,...])[i]
        
    return traj, r_traj
    
# Plot phase plot, X traj and reward traj for various levels of optimism/pessimism
def compare_levels(env,  # environment
                   level_list,  # list of levels
                   gamma,  # discount factor
                   beta,  # choice intensity
                   Rmin,  # min reward perceived
                   Rmax,  # max reward perceived
                   xinds:tuple,  # which phase space axes to plot along x axes
                   res,  # specify range & resolution
                   algo='SARSA',  # specify algorithm: 'SARSA' or 'AC'
                   nrb:int=29,  # number of neurons
                   discsig:float=0.05,  # discretization sigma
                   lr:float=0.1,  # learning rate
                   traj_len:int=500,  # trajectory length
                   otherXs=None,  # if 2nd condition: values of X along this condition
                   cmap='viridis',  # colormap
                   save=False,  # save fig?
                   savename=None,  # saved figure's name
                   axes=None,  # Axes to plot into
                   ):  
   

    # Fig and Axes
    # Style
    sns.set_style("whitegrid")
    sns.set_context("paper", font_scale=1.5, rc={"lines.linewidth": 2})
    
    # Subplots: phase plot, X traj, reward traj
    fig, (ax1, ax2, ax3) = plt.subplots(1, 3, figsize=(4.5 * 3.8, 3.8))
    
    # Colormap for the different lines
    cmap = mpl.colormaps[cmap]
    ext = np.linspace(0, 1, len(level_list))  # extent of colormap
    colors = cmap(tuple(ext))
    # Neutral agent is represented with a black line
    colors[int(len(level_list)/2)] = [0, 0, 0, 1]  
    
    # Zero line
    zero = np.zeros((len(res))) 

    # Loop over optimism/pessimism levels
    for j, level in enumerate(level_list):
        
        # Define agent-environment interface
        if algo=='SARSA':
            aei = DDRLSarsa(env, nr_reward_bins=nrb, discretization_sigma=discsig, 
                            learning_rates=lr, discount_factors=gamma, 
                            choice_intensities=beta, Rmin=Rmin, Rmax=Rmax,
                            method="weights", wU=level, use_prefactor=True)
        elif algo=='AC':
            aei = DDRLActorCritic(env, nr_reward_bins=nrb, discretization_sigma=discsig, 
                                  learning_rates=lr, discount_factors=gamma, 
                                  Rmin=Rmin, Rmax=Rmax,
                                  method="weights", wU=level, use_prefactor=True)
 
        # Obtain the dXs for y-axis of phase plot
        dXs = obtain_dXs(aei, res, xinds, traj_len, otherXs)
        
        # Phase plot
        ax1.plot(res, dXs[0, :], color=colors[j])
        ax1.plot(res, zero, color="grey", ls='dashed')  # plot zero line
        
        # Obtain X traj and reward traj
        X0 = np.ones((aei.N, aei.Z, aei.M)) * 0.5  # init random strategy
        X_traj, r_traj = reward_traj(aei, X0, 0, traj_len=traj_len)
        
        # X traj plot
        ax2.plot(np.arange(0, traj_len), X_traj[:,0,0,0], 
                 color=colors[j], label=r'$w_{U}=$'+str(level))
        
        # Reward plot
        ax3.plot(np.arange(0, traj_len), r_traj, 
                 color=colors[j], label=r'$w_{U}=$'+str(level))
        
    # Decorations
    ax1.set_ylabel(r"$dX$")
    ax1.set_xlabel("strategy "+r'$X$')
    ax1.set_title('phase plot')
    ax2.set_xlabel("time step "+r'$t$')
    ax2.set_ylabel("strategy "+r'$X^{0,0,0}(t)$')
    ax2.set_title('strategy over time')
    ax3.set_xlabel("time step "+r'$t$')
    ax3.set_ylabel("reward "+r'$R^{0}(t)$')
    ax3.set_title('mean reward over time')
    ax3.legend(bbox_to_anchor=(1.01, 1.01), title='weights '+r'$w_U$')
    fig.tight_layout()
    
    # Save figure
    if save == True:
        plt.savefig(savename, dpi=300, bbox_inches='tight', format='eps')


