## Functions for comparisons between DDRL biasing methods and asymmetric RL

# Compute Q-value gap at steady state
def deltaQinf(p0,  # reward prob of arm 1 
              p1,  # reward prob of arm 2
              b):  # bias strength
    return ((p0 * b - (1 - p0)) / (p0 * b + (1 - p0))) - ((p1 * b - (1 - p1)) / (p1 * b + (1 - p1)))

# Compute prob of choosing most rewarding arm at steady state
def Xinf(dQ,  # Q-value gap
         beta):  # choice intensity
    return 1 / (1 + np.exp(beta * (-dQ)))

# Compute final strategies for quantile, expectile, weights, and asymRL methods
def compute_comparisons(p0,  # reward prob of arm 1
                        p1,  # reward prob of arm 2
                        b_ratios,  # bias strengths for asymRL
                        q_list,  # quantiles
                        e_list,  # expectiles
                        w_list,  # weights
                        gamma,  # discount factor
                        beta,  # choice intensity
                        Rmin,  # min reward perceived
                        Rmax,  # max reward perceived
                        nrb:int=29,  # number of neurons
                        discsig:float=0.05,  # discretization sigma
                        lr:float=0.1,  # learning rate
                        axes=None,  # axes to plot into
                        ):
    
    # Create 2-armed bandit
    xs = np.array([[-1, 1],
                   [-1, 1]])
    ps = np.array([[1-p0, p0],
                   [1-p1, p1]])
    env = TwoArmedBandit(disttype='discrete', xs=xs, ps=ps)
    
    # Compute asymRL Xinf for each bias strength
    b_dQs = deltaQinf(p0, p1, b_ratios)  # Q-value gaps
    b_xinf = Xinf(b_dQs, beta)  # final strategies
    
    # Compute quantile Xinf for each quantile
    q_xinf = np.zeros((len(q_list)))
    for i, q in enumerate(q_list):
        # Define agent-env interface
        aei = DDRLSarsa(env, nr_reward_bins=nrb, discretization_sigma=discsig, 
                        learning_rates=lr, discount_factors=gamma,
                        choice_intensities=beta, Rmin=Rmin, Rmax=Rmax,
                        method='quantile', tau=q, use_prefactor=False)
        # Initial strategy
        X = 0.5 * np.ones((aei.N, aei.Z, aei.M))
        # Compute strategy trajectory
        traj, fpreached = aei.trajectory(X, 150)
        # Take the last X^{0,0,0} of the trajectory
        q_xinf[i] = traj[-1, 0, 0, 0]
        
    # Compute expectile Xinf for each expectile
    e_xinf = np.zeros((len(e_list)))
    for i, e in enumerate(e_list):
        # Define agent-env interface
        aei = DDRLSarsa(env, nr_reward_bins=nrb, discretization_sigma=discsig, 
                        learning_rates=lr, discount_factors=gamma,
                        choice_intensities=beta, Rmin=Rmin, Rmax=Rmax,
                        method='expectile', tau=e, use_prefactor=False)
        # Initial strategy
        X = 0.5 * np.ones((aei.N, aei.Z, aei.M))
        # Compute strategy trajectory
        traj, fpreached = aei.trajectory(X, 150)
        # Take the last X^{0,0,0} of the trajectory
        e_xinf[i] = traj[-1, 0, 0, 0]
        
    # Compute weights Xinf for each upper weight value
    w_xinf = np.zeros((len(w_list)))
    for i, w in enumerate(w_list):
        # Define agent-env interface
        aei = DDRLSarsa(env, nr_reward_bins=nrb, discretization_sigma=discsig, 
                        learning_rates=lr, discount_factors=gamma,
                        choice_intensities=beta, Rmin=Rmin, Rmax=Rmax,
                        method='weights', wU=w, use_prefactor=False)
        # Initial strategy
        X = 0.5 * np.ones((aei.N, aei.Z, aei.M))
        # Compute strategy trajectory
        traj, fpreached = aei.trajectory(X, 150)
        # Take the last X^{0,0,0} of the trajectory
        w_xinf[i] = traj[-1, 0, 0, 0]
        
    return b_xinf, q_xinf, e_xinf, w_xinf

# Plot the final strategies
def plot_comparisons(b_ratios, q_list, e_list, w_list, b_xinf, q_xinf, 
                     e_xinf, w_xinf, scarcity="poor", save=False,
                     savename=None):
    
    # Style
    sns.set_style("whitegrid")
    sns.set_context("paper", font_scale=1.5, rc={"lines.linewidth": 2})
    # Subplots: quantile, expectile, weights
    fig, (ax1, ax2, ax3) = plt.subplots(1, 3, figsize=(4.5 * 3.8, 4.5))
    axes = [ax1, ax2, ax3]
    # Twin axes and their properties
    ax11 = ax1.twiny()
    ax22 = ax2.twiny()
    ax33 = ax3.twiny()
    twin_axes = [ax11, ax22, ax33]
    ddrl_lists = [q_list, e_list, w_list]
    ddrl_xinfs = [q_xinf, e_xinf, w_xinf]
    colors = ['red', 'green', 'orange']
    labels = ['quantile', 'expectile', 'DDRL']
    xlabels = [r'$\tau$', r'$\tau$', 'weight '+r'$w_U$']
    
    # to find the bias strength of the neutral asymRL agent
    ind = np.sum(b_ratios < 1)
    
    # The plots
    for i, ax in enumerate(axes):
        ax.set_xscale('log')  # log scale for x-axis
        # Plot Xinfs for asym RL
        ax.plot(b_ratios, b_xinf, '-+', mew=3, ms=8, color='blue', label="asym RL")
        # Plot neutral line
        ax.plot(b_ratios, np.repeat(b_xinf[ind], len(b_ratios)), '--', color='gray')
        # Plot Xinfs for DDRL method
        if i==1:
            axes[i].plot(b_ratios, ddrl_xinfs[i], '-o', color=colors[i],
                         label=labels[i])
        else:
            twin_axes[i].plot(ddrl_lists[i], ddrl_xinfs[i], '-o', color=colors[i],
                              label=labels[i])
        
   
    # Instructions for specific axes
    ax33.set_xscale('log')
    
    # Decorations
    for i, ax in enumerate(axes):
        if scarcity=="poor":
            ax.legend(loc='upper left')
        else: 
            ax.legend(loc='upper right')
        ax.set_xlabel('bias strength '+r'$b$', color="blue")  
        ax.xaxis.label.set_color('blue')
        ax.tick_params(axis='x', colors='blue')
        ax.spines['bottom'].set_color('blue')
        ax.spines['top'].set_color(colors[i])
        twin_axes[i].set_xlabel(xlabels[i], color=colors[i])
        twin_axes[i].xaxis.label.set_color(colors[i])
        twin_axes[i].tick_params(axis='x', colors=colors[i])
        twin_axes[i].spines['bottom'].set_color('blue')
        twin_axes[i].spines['top'].set_color(colors[i])
    
    # Decorations for specific axes    
    ax1.set_ylabel('final strategy '+r'$X_{\infty}$')
    # ax22.set_xticks(e_list)
    
    if scarcity=="poor":
        ax11.legend(loc="center left")
        ax33.legend(loc='center left')
    else:
        ax11.legend(loc='center right')
        ax33.legend(loc='center right')
    
    ax1.set_title("asymmetric RL vs. quantiles")
    ax2.set_title("asymmetric RL vs. expectiles")
    ax3.set_title("asymmetric RL vs. DDRL in a poor environment")
    
    fig.tight_layout()
    
    # Save figure
    if save == True:
        plt.savefig(savename, dpi=300, bbox_inches='tight', format='eps')

