## Functions to plot 3 flowplots and associated trajectories

# Plot the flowplots together
def plot_3flowplots(aeis,  # list of aeis
                    x:tuple,  # which phase space axes to plot along x axes
                    y:tuple,  # which phase space axes to plot along y axes
                    NrRandom:int=4,  # number of random strategies to average over
                    Xinits=None,  # initial Xs to plot trajectories
                    decorate=False,  # whether to decorate the axes or not
                    titles=None,  # list of titles for 3 plots
                    xlabel=None,  # x-label
                    ylabel=None,  # y-label
                    cols=None,  # list of colors for trajectories
                    cmap='viridis',  # Colormap
                    axes=None,  # Axes to plot into
                    ):
    
    # Style
    sns.set_style("white")
    sns.set_context("paper", font_scale=1.25, rc={"lines.linewidth": 2})
    
    # Plot the flow plot
    for i, ax in enumerate(axes):
        aei = aeis[i]
        fp.plot_strategy_flow(aei, x, y, flowarrow_points = np.linspace(0.01 ,0.99, 9), 
                              use_RPEarrows=False, NrRandom=NrRandom, cmap=cmap, axes=ax)
        
        # Plot trajectory if initial strategies are specified
        if Xinits != None:
            trajs = []  # trajectories
            fprs = []  # are fixed points reached?
            for _, Xinit in enumerate(Xinits):
                trj, fpr = aei.trajectory(Xinit, Tmax=12000, tolerance=1e-6)
                trajs.append(trj)
                fprs.append(fpr)
                
            fp.plot_trajectories(trajs, x, y, fprs=fprs, axes=ax, cols=cols)
    
    # Add titles, xlabels and ylabels to subplots if needed
    if decorate==True:
        for i, ax in enumerate(axes): 
            ax.set_xlabel(xlabel)
            ax.set_title(titles[i])
        
        axes[0].set_ylabel(ylabel)

# %% ../../nbs/04.03_PlottingTools.ipynb #35d10ab4
def compile_strategy(p0c:float,  # cooperation probability of agent zero
                     p1c:float):  # cooperation probability of agent one
    strat = np.zeros((2, 1, 2))
    strat[0, 0, 0] = p0c
    strat[1, 0, 0] = p1c
    strat[0, 0, 1] = 1 - p0c
    strat[1, 0, 1] = 1 - p1c
    return strat                         

def plot_separatrix(aei, ax, x, y):    
    # Add saddle node
    # by reversing the dynamics from two agents with identical strategies
    o = [0.5, 0.5]; o = compile_strategy(*o)
    for _ in range(1000): o, _ = aei.reverse_step(o)
    # Add separatrix
    o = o[:, 0, 0] - np.array([0, 0.0001])
    o1 = compile_strategy(*o)
    o2 = compile_strategy(*o[::-1])
    sep1=[]; sep2=[]
    for _ in range(1000): o1, _ = aei.reverse_step(o1); sep1.append(o1)
    for _ in range(1000): o2, _ = aei.reverse_step(o2); sep2.append(o2)
    fp.plot_trajectories([sep1, sep2], x=x, y=y, cols=['dimgray'], lws=[1],
                         lss=['--'], alphas=[0.95], axes=ax)

# %% ../../nbs/04.03_PlottingTools.ipynb #e1392959
def fill_containers(env, Xrisk, Xsafe, discountfactors, weights):
    risky_optimal_data_container = np.zeros((discountfactors.size, weights.size, 2))
    risky_stable_container = np.zeros((discountfactors.size, weights.size, 2))
    safe_stable_container = np.zeros((discountfactors.size, weights.size, 2))
    for i, dcf in enumerate(discountfactors):
        for j, w in enumerate(weights):
            aei = DDRLActorCritic(env, nr_reward_bins=29, discretization_sigma=0.05, 
                                  learning_rates=0.1, discount_factors=dcf, 
                                  Rmin=0, Rmax=1,
                                  method="weights", wU=w, use_prefactor=True)
            Visa_risk = aei.Visa(Xrisk)
            dX_risk = aei.step(Xrisk)[0] - Xrisk
            risky_stable_container[i, j, :] = dX_risk[0, :, 0] <= 0
            ag = 0; a = 1; s = 2
            Vis_risk = jnp.einsum(Visa_risk, [ag, s, a], Xrisk, [ag, s, a], [ag, s])
            Visa_safe = aei.Visa(Xsafe)
            dX_safe = aei.step(Xsafe)[0] - Xsafe
            safe_stable_container[i, j, :] = dX_safe[0, :, 0] >= 0
            Vis_safe = jnp.einsum(Visa_safe, [ag, s, a], Xsafe, [ag, s, a], [ag, s])
            risky_optimal_data_container[i, j, :] = Vis_risk[0,:] > Vis_safe[0,:]
            print("gamma = "+str(dcf)+", w = "+str(w)+" done")
    safe_stable_container = safe_stable_container * 2
    indicator_stable = safe_stable_container + risky_stable_container
    return risky_optimal_data_container, indicator_stable
